pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Mint 100 tokens to address(this) so it has balance
        c.mintSynth(address(this), 100);
        // Approve c itself (as spender) to allow burnFrom
        c.approve(address(c), 100);
        // Record totalSupply before burn
        uint256 supplyBefore = c.totalSupply();
        // Burn 100 tokens from address(this) via burnFrom
        c.burnFrom(address(this), 100);
        // After burn: reference totalSupply = supplyBefore - 100, mutant totalSupply = supplyBefore
        assertTrue(c.totalSupply() == supplyBefore - 100);
    }
}

